    'locations': {
       'start': {'description': 'You are at the start of the adventure'},
        'forest': {'description': 'You are in a dark forest'},
        'cave': {'description': 'You are in a dark cave'}
    },
    'player': {'location':'start'},
    'player_inventory': []
}

